 *             %m_uc_compare_tables(
 *                base   = SASHELP.class
 *              , comp   = WORK.class
 *              , print  = Y
 *              , debug  = N
 *                );
 * \endcode
 * 
 * \example    Example 6: Compare SASHELP.class against WORK.class with IDCOLS value change:
 * \code
 *             data WORK.class;
