                  %else %let list = %sysfunc(strip(&list.)) %sysfunc(strip(&varnam.));
               %end;
            %end;
            %else %do;
               %if %length(&list.) eq 0 %then %let list= %sysfunc(strip(&varnam.));
               %else %let list = %sysfunc(strip(&list.)) %sysfunc(strip(&varnam.));
            %end;

         %end;

