   %*-------------------------------------------------------------------------;
   %* Set local macro variables and initialize environment:                   ;
   %*-------------------------------------------------------------------------;

   %local
      date
      delim
      dexist
      dsid
      fetch
      fexist
      flvls
      fname
      fnum
      fpath
      fsize
      mode
      msg1
      msg2
      msg3
      msg4
      msg5
      msg6
      msg7
      msg8
      msg9
      prgm
      rpath
      start
      status
      stop
      time
